<script setup lang="ts">
import {requestApi} from '../api/client';
import {computed,reactive,ref,onMounted} from 'vue';
import {ElAlert,ElButton,ElCard,ElDescriptions,ElDescriptionsItem,ElDialog,ElForm,ElFormItem,ElInput,ElOption,ElPagination,ElSelect,ElTable,ElTableColumn,ElTag,type FormInstance} from 'element-plus';
type Row=Record<string,any>;
const rows=ref<Row[]>([]),entities=ref<string[]>([]),total=ref(0),page=ref(1),query=ref(''),entity=ref(''),status=ref('active');
const busy=ref(false),error=ref(''),notice=ref(''),dialog=ref(''),selected=ref<Row|null>(null),formRef=ref<FormInstance>(),form=reactive<Row>({});
const names:Row={source_records:'需求来源',attachments:'附件',project_change_orders:'项目变更单',project_stage_events:'阶段确认',project_demand_scopes:'项目需求范围',reference_price_versions:'价格历史版本',ledger_towers:'杆塔台账',ledger_spans:'档距台账',transmission_lines:'线路台账',demand_duplicate_reviews:'重复需求核查',frameworks:'年度框架',agreements:'执行协议',projects:'子项目',demands:'专业需求',demand_batches:'需求批次',dictionary_items:'数据字典',voltage_levels:'电压等级',project_settlement_entries:'结算凭证',project_approval_versions:'批准版本',completion_records:'完成记录',executions:'检修计划',execution_items:'计划明细',reference_price_catalog:'参考单价',manual_notes:'手工记录',ledger_lines:'线路台账',physical_towers:'实体杆塔',logical_towers:'线路杆塔',line_spans:'档距',allowed_ips:'访问授权'};
const actions:Row={create:'新增',update:'修改',delete:'删除',annotate:'纠错说明',hide:'删除显示',show:'恢复显示',record:'手工登记',record_payment:'结算登记',record_reversal:'结算冲销',status_active:'启用',status_inactive:'停用',reorder:'调整顺序',revise:'修订'};
const fields:Row={name:'名称',title:'名称',fiscal_year:'框架年度',limit_fen:'授权额度（元）',approved_budget_fen:'批准预算（元）',amount_fen:'金额（元）',quantity_scaled:'工作量',status:'状态',settlement_no:'凭证编号',evidence:'依据',message:'记录内容'};
const differences=computed(()=>Object.keys(fields).filter(key=>selected.value?.before?.[key]!==undefined||selected.value?.after?.[key]!==undefined).map(key=>({key,label:fields[key],before:display(key,selected.value?.before?.[key]),after:display(key,selected.value?.after?.[key])})));
function display(key:string,value:any){if(value==null)return '—';if(key.endsWith('_fen'))return (value/100).toFixed(2);if(key==='quantity_scaled')return String(value/10000);if(key==='status')return ({active:'启用',inactive:'停用',approved:'已立项',reserve:'储备',stocked:'已入库',deleted:'已删除'} as Row)[value]||value;return String(value)}
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const api=(path:string,method='GET',body?:Row)=>requestApi(path,method,body);
async function load(reset=false){busy.value=true;error.value='';if(reset)page.value=1;try{const data=await api('/audit-records?'+new URLSearchParams({page:String(page.value),search:query.value,entity:entity.value,status:status.value}));rows.value=data.items;entities.value=data.entities;total.value=data.total}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function open(action:string,item?:Row){
 error.value='';try{selected.value=item?await api('/audit-records/'+item.id):null;Object.keys(form).forEach(key=>delete form[key]);Object.assign(form,{message:'',note:selected.value?.note||'',reason:''});dialog.value=action}catch(e){error.value=(e as Error).message}
}
async function save(){
 if(busy.value||!await formRef.value?.validate().catch(()=>false))return;busy.value=true;error.value='';
 try{
  if(dialog.value==='new')await api('/audit-records','POST',{message:form.message});
  else await api('/audit-records/'+selected.value!.id+(dialog.value==='restore'?'/restore':''),dialog.value==='edit'?'PATCH':dialog.value==='delete'?'DELETE':'POST',{version:selected.value!.version,note:form.note,reason:form.reason});
  dialog.value='';await load();notice.value='操作记录已更新，原始事实保留';
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
onMounted(()=>load());
</script>
<template>
 <section class="dictionary-ui audit-workspace"><ElCard shadow="never"><template #header><div class="section-header"><div><h2>操作记录</h2><p class="muted">查询业务操作、补充纠错说明，删除显示后仍保留原始事实和处理历史。</p></div><ElButton type="primary" :disabled="busy" @click="open('new')">新增记录</ElButton></div></template>
  <div class="audit-toolbar"><ElInput v-model="query" aria-label="搜索操作记录" placeholder="搜索记录内容、操作人或关联标识" clearable @keyup.enter="load(true)"/><ElSelect v-model="entity" aria-label="业务类型" :empty-values="[null,undefined]" @change="load(true)"><ElOption label="全部业务类型" value=""/><ElOption v-for="key in entities" :key="key" :label="names[key]||'其他业务记录'" :value="key"/></ElSelect><ElSelect v-model="status" aria-label="记录状态" @change="load(true)"><ElOption label="正常记录" value="active"/><ElOption label="已删除" value="deleted"/><ElOption label="全部记录" value="all"/></ElSelect><ElButton :disabled="busy" @click="load(true)">查询</ElButton></div>
  <ElAlert v-if="error&&!dialog" :title="error" type="error" :closable="false"/><p v-if="notice" role="status" class="dictionary-notice">{{notice}}</p>
  <ElTable :data="rows" row-key="id" empty-text="暂无符合条件的记录"><ElTableColumn label="时间" width="180"><template #default="{row}">{{time(row.created_at)}}</template></ElTableColumn><ElTableColumn label="业务类型" width="130"><template #default="{row}">{{names[row.entity]||'其他业务'}}</template></ElTableColumn><ElTableColumn label="操作" width="105"><template #default="{row}">{{actions[row.action]||'业务处理'}}</template></ElTableColumn><ElTableColumn prop="actor_name" label="操作人" width="110"/><ElTableColumn label="内容 / 纠错说明" min-width="220"><template #default="{row}">{{row.note||row.reason||'初始登记'}}<ElTag v-if="row.note" size="small" type="info">已补充说明</ElTag></template></ElTableColumn><ElTableColumn label="状态" width="85"><template #default="{row}"><ElTag :type="row.status==='deleted'?'info':'success'">{{row.status==='deleted'?'已删除':'正常'}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="190" fixed="right"><template #default="{row}"><ElButton link type="primary" @click="open('detail',row)">详情</ElButton><ElButton v-if="row.status!=='deleted'" link type="primary" @click="open('edit',row)">编辑说明</ElButton><ElButton v-if="row.status!=='deleted'" link type="danger" @click="open('delete',row)">删除</ElButton><ElButton v-else link type="primary" @click="open('restore',row)">恢复显示</ElButton></template></ElTableColumn></ElTable>
  <div class="audit-pagination"><span>共 {{total}} 条</span><ElPagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load()"/></div>
 </ElCard>
 <ElDialog :model-value="!!dialog" @update:model-value="value=>{if(!value)dialog=''}" :title="dialog==='new'?'新增操作记录':dialog==='edit'?'编辑纠错说明':dialog==='delete'?'删除操作记录':dialog==='restore'?'恢复操作记录':'操作记录详情'" class="dictionary-ui dictionary-dialog" :width="dialog==='detail'?'760px':'540px'" align-center append-to-body destroy-on-close :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy">
  <template v-if="dialog==='detail'&&selected"><ElDescriptions :column="2" border><ElDescriptionsItem label="业务类型">{{names[selected.entity]||'其他业务'}}</ElDescriptionsItem><ElDescriptionsItem label="操作人">{{selected.actor_name}}</ElDescriptionsItem><ElDescriptionsItem label="原始时间">{{time(selected.created_at)}}</ElDescriptionsItem><ElDescriptionsItem label="当前状态">{{selected.status==='deleted'?'已删除':'正常'}}</ElDescriptionsItem><ElDescriptionsItem label="原始说明" :span="2">{{selected.reason||'初始登记'}}</ElDescriptionsItem><ElDescriptionsItem label="当前纠错说明" :span="2">{{selected.note||'尚未补充'}}</ElDescriptionsItem></ElDescriptions><h3>原始记录内容</h3><ElTable :data="differences" empty-text="此操作的原始内容保存在业务快照中"><ElTableColumn prop="label" label="内容"/><ElTableColumn prop="before" label="操作前"/><ElTableColumn prop="after" label="操作后"/></ElTable><h3>纠错与显示处理历史</h3><div v-for="event in selected.maintenance_history" :key="event.id" class="audit-maintenance"><strong>{{actions[event.action]}}</strong><span>{{event.actor_name}} · {{time(event.created_at)}}</span><p>{{event.reason}}</p><p v-if="event.entity==='audit_annotations'">{{event.value.note||'清除纠错说明'}}</p></div><p v-if="!selected.maintenance_history.length" class="muted">尚无后续处理。</p></template>
  <ElForm v-else novalidate ref="formRef" :model="form" label-position="top" :disabled="busy" @submit.prevent="save"><ElAlert v-if="dialog==='delete'||dialog==='restore'" :title="dialog==='delete'?'仅从正常操作记录中移除，不撤销对应业务，也不清除原始事实。':'恢复到正常操作记录列表，原始事实不变。'" type="info" show-icon :closable="false"/><ElFormItem v-if="dialog==='new'" label="记录内容" prop="message" :rules="[{required:true,whitespace:true,message:'请填写记录内容',trigger:'blur'}]"><ElInput v-model="form.message" aria-label="记录内容" type="textarea" :rows="4" maxlength="2000"/></ElFormItem><ElFormItem v-if="dialog==='edit'" label="纠错说明" prop="note"><ElInput v-model="form.note" aria-label="纠错说明" type="textarea" :rows="4" maxlength="2000"/><small class="muted">原文继续保留；留空表示清除当前纠错说明。</small></ElFormItem><ElFormItem v-if="dialog!=='new'" label="处理依据" prop="reason" :rules="[{required:true,whitespace:true,message:'请填写处理依据',trigger:'blur'}]"><ElInput v-model="form.reason" aria-label="处理依据" type="textarea" :rows="2" maxlength="2000"/></ElFormItem><p v-if="error" role="alert" class="dictionary-form-error">{{error}}</p><div class="dictionary-dialog-footer"><ElButton :disabled="busy" @click="dialog=''">取消</ElButton><ElButton :type="dialog==='delete'?'danger':'primary'" native-type="submit" :loading="busy">{{dialog==='delete'?'确认删除':dialog==='restore'?'确认恢复':'保存'}}</ElButton></div></ElForm>
 </ElDialog></section>
</template>
<style scoped>
.audit-toolbar{display:flex;gap:12px;margin-bottom:18px;flex-wrap:wrap}.audit-toolbar>.el-input{flex:1;min-width:190px}.audit-toolbar>.el-select{width:160px}.audit-pagination{display:flex;justify-content:space-between;align-items:center;margin-top:18px;font-size:12px;color:#889bb2}.section-header{margin-bottom:0}.audit-maintenance{padding:12px 0;border-bottom:1px solid #e8eef8;font-size:12px}.audit-maintenance>span{margin-left:12px;color:#8a9db4}.audit-maintenance p{margin:7px 0 0;color:#617c9c}
@media(max-width:850px){.audit-toolbar>.el-select{flex:1;min-width:130px;width:auto}}
</style>
